import 'dart:io';

import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

import '../engine/obj_mesh.dart';

/// 3D effect models loaded from assets/effects/*.obj (+ effects.mtl),
/// generated by tool/generate_effects.dart. Effects are skipped while unloaded.
class Fx {
  static const dir = 'assets/effects';
  static const names = [
    'slash_arc', 'shockwave_ring', 'impact_flash', 'smoke_puff', 'dust_puff', 'flame', 'spark',
    'ember', 'streak', 'blood_drop', 'petal', 'shuriken', 'arrow', 'alert_mark', 'suspicion_gem',
    'blind_stars', 'objective_beacon', 'objective_gem', 'pickup_ring', 'pickup_scroll',
    'pickup_supply', 'pickup_onigiri', 'bar_quad',
  ];

  static final Map<String, ObjMesh> meshes = {};

  /// Load problems per file (parse errors, skipped faces). Empty when clean.
  static final Map<String, List<String>> problems = {};
  static Future<void>? _loading;

  static bool get loaded => meshes.length == names.length;

  /// Loads from the Flutter asset bundle (the app). Never throws: a broken
  /// file only disables that effect and is reported in [problems].
  static Future<void> load() => _loading ??= _loadWith(rootBundle.loadString);

  /// Loads straight from disk (tests and tools; run from the project root).
  static void loadFromDirectory([String path = dir]) {
    if (loaded) return;
    var mtl = <String, ObjMaterial>{};
    try {
      mtl = ObjMesh.parseMtl(File('$path/effects.mtl').readAsStringSync());
    } catch (e) {
      _report('effects.mtl', ['$e']);
    }
    for (final n in names) {
      _add(n, () => File('$path/$n.obj').readAsStringSync(), mtl);
    }
  }

  static Future<void> _loadWith(Future<String> Function(String) read) async {
    var mtl = <String, ObjMaterial>{};
    try {
      mtl = ObjMesh.parseMtl(await read('$dir/effects.mtl'));
    } catch (e) {
      _report('effects.mtl', ['$e']);
    }
    for (final n in names) {
      String? src;
      try {
        src = await read('$dir/$n.obj');
      } catch (e) {
        _report('$n.obj', ['cannot read: $e']);
        continue;
      }
      _add(n, () => src!, mtl);
    }
  }

  static void _add(String n, String Function() source, Map<String, ObjMaterial> mtl) {
    try {
      final m = ObjMesh.parse(n, source(), mtl);
      if (m.triangleCount > 0) meshes[n] = m;
      _report('$n.obj', [...m.warnings, if (m.triangleCount == 0) 'no valid triangles — effect disabled']);
    } catch (e) {
      _report('$n.obj', ['parse failed — effect disabled: $e']);
    }
  }

  static void _report(String file, List<String> issues) {
    if (issues.isEmpty) return;
    problems[file] = issues;
    debugPrint('[Fx] $file:\n  ${issues.join('\n  ')}');
  }

  static ObjMesh? get slashArc => meshes['slash_arc'];
  static ObjMesh? get ring => meshes['shockwave_ring'];
  static ObjMesh? get flash => meshes['impact_flash'];
  static ObjMesh? get smoke => meshes['smoke_puff'];
  static ObjMesh? get dust => meshes['dust_puff'];
  static ObjMesh? get flame => meshes['flame'];
  static ObjMesh? get spark => meshes['spark'];
  static ObjMesh? get ember => meshes['ember'];
  static ObjMesh? get streak => meshes['streak'];
  static ObjMesh? get blood => meshes['blood_drop'];
  static ObjMesh? get petal => meshes['petal'];
  static ObjMesh? get shuriken => meshes['shuriken'];
  static ObjMesh? get arrow => meshes['arrow'];
  static ObjMesh? get alert => meshes['alert_mark'];
  static ObjMesh? get suspicion => meshes['suspicion_gem'];
  static ObjMesh? get blind => meshes['blind_stars'];
  static ObjMesh? get beacon => meshes['objective_beacon'];
  static ObjMesh? get gem => meshes['objective_gem'];
  static ObjMesh? get pickupRing => meshes['pickup_ring'];
  static ObjMesh? get scroll => meshes['pickup_scroll'];
  static ObjMesh? get supply => meshes['pickup_supply'];
  static ObjMesh? get onigiri => meshes['pickup_onigiri'];
  static ObjMesh? get bar => meshes['bar_quad'];
}
